39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	};
50	
51	const policyBasePremium = (items: Item[]): number =>
52	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
53	
54	const quotePremium = (items: Item[]): number => {
55	  const base = policyBasePremium(items);
56	  const surcharge = percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
57	  return Math.ceil(base + surcharge + PROCESSING_FEE);
58	};
59	
60	const runStep = (step: Step): StepResult => {
61	  if (step.op === "quote") return { premium: quotePremium(step.items) };
62	  throw new Error("claim steps are not implemented yet");
63	};
64	
65	export const runScenario = (scenario: Scenario): ScenarioResult => ({
66	  results: scenario.steps.map(runStep),
67	});
